def invertTree(root):
    if not root:
        return []
    class Node:
        def __init__(self, val):
            self.val = val
            self.left = None
            self.right = None
    root_node = Node(root[0])
    q = [root_node]
    i = 1
    while q and i < len(root):
        curr = q.pop(0)
        if i < len(root) and root[i] is not None:
            curr.left = Node(root[i])
            q.append(curr.left)
        i += 1
        if i < len(root) and root[i] is not None:
            curr.right = Node(root[i])
            q.append(curr.right)
        i += 1
    def invert(node):
        if not node:
            return None
        node.left, node.right = invert(node.right), invert(node.left)
        return node
    invert(root_node)
    res = []
    q = [root_node]
    while q:
        curr = q.pop(0)
        if curr:
            res.append(curr.val)
            q.append(curr.left)
            q.append(curr.right)
    return res

