    if not root or root[0] is None:
        return 0
    def get_depth(idx):
        if idx >= len(root) or root[idx] is None:
            return 0
        return 1 + max(get_depth(2 * idx + 1), get_depth(2 * idx + 2))
    return get_depth(0)

