    candidates.sort()
    res = []
    def backtrack(start, remain, curr):
        if remain == 0:
            res.append(list(curr))
            return
        for i in range(start, len(candidates)):
            if candidates[i] > remain:
                break
            curr.append(candidates[i])
            backtrack(i, remain - candidates[i], curr)
            curr.pop()
    backtrack(0, target, [])
    return res

