    def backtrack(open_c, close_c, curr):
        if len(curr) == 2 * n:
            res.append(curr)
            return
        if open_c < n:
            backtrack(open_c + 1, close_c, curr + "(")
        if close_c < open_c:
            backtrack(open_c, close_c + 1, curr + ")")
    backtrack(0, 0, "")
    return res

