def wordBreak(s, wordDict):
    d = set(wordDict)
    memo = {}
    def dfs(rem):
        if rem in memo:
            return memo[rem]
        if not rem:
            return [""]
        res = []
        for word in wordDict:
            if rem.startswith(word):
                sub_res = dfs(rem[len(word):])
                for sub in sub_res:
                    res.append(word if not sub else word + " " + sub)
        memo[rem] = res
        return res
    return dfs(s)

