    res = []
    def backtrack(idx, path):
        if idx == len(s):
            res.append(''.join(path))
            return
        if s[idx].isalpha():
            backtrack(idx + 1, path + [s[idx].lower()])
            backtrack(idx + 1, path + [s[idx].upper()])
        else:
            backtrack(idx + 1, path + [s[idx]])
    backtrack(0, [])
    return sorted(res)

