def filteredSubsets(nums: list[int], k: int) -> int:
    count = 0
    def dfs(idx, curr_sum, count_items):
        nonlocal count
        if idx == len(nums):
            if count_items > 0 and curr_sum >= k:
                count += 1
            return
        dfs(idx + 1, curr_sum + nums[idx], count_items + 1)
        dfs(idx + 1, curr_sum, count_items)
    dfs(0, 0, 0)
    return count

