def countPathsToLeaf(tree: list) -> int:
    if not tree or tree[0] is None: return 0
    def dfs(idx):
        if idx >= len(tree) or tree[idx] is None: return 0
        left, right = 2 * idx + 1, 2 * idx + 2
        has_left = left < len(tree) and tree[left] is not None
        has_right = right < len(tree) and tree[right] is not None
        if not has_left and not has_right: return 1
        return dfs(left) + dfs(right)
    return dfs(0)

