def getMaximumGold(grid: list[list[int]]) -> int:
    m, n = len(grid), len(grid[0])
    def dfs(r, c):
        if r < 0 or r >= m or c < 0 or c >= n or grid[r][c] == 0: return 0
        gold = grid[r][c]
