def permuteDiffTwo(n: int) -> list[list[int]]:
    nums = list(range(1, n + 1))
    res = []
    used = [False] * n
    def backtrack(curr):
        if len(curr) == n:
            res.append(list(curr))
            return
        for i in range(n):
            if not used[i]:
                if not curr or abs(curr[-1] - nums[i]) >= 2:
                    used[i] = True
                    curr.append(nums[i])
                    backtrack(curr)
                    curr.pop()
                    used[i] = False
    backtrack([])
    return sorted(res)

