                    cnt[target[i]] -= 1
                    next_mask |= (1 << i)
            if next_mask != mask:
                ans = min(ans, 1 + dfs(next_mask))
        memo[mask] = ans
        return ans
    res = dfs(0)
    return res if res != float('inf') else -1

