                    best_val = c + sub_c
                    best_path = [v] + sub_p
        memo[(mask, u)] = (best_val, best_path)
        return memo[(mask, u)]
    _, path = tsp(0, -1)
    res = words[path[0]]
    for i in range(1, len(path)):
