def knightsTour(n: int) -> list[list[int]]:
    board = [[-1] * n for _ in range(n)]
    moves = [(2, 1), (1, 2), (-1, 2), (-2, 1), (-2, -1), (-1, -2), (1, -2), (2, -1)]
    def get_deg(r, c):
        count = 0
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and board[nr][nc] == -1:
                count += 1
        return count
    board[0][0] = 0
    def solve(r, c, step):
        if step == n * n:
            return True
        nxt_moves = []
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and board[nr][nc] == -1:
                nxt_moves.append((get_deg(nr, nc), nr, nc))
        nxt_moves.sort()
        for _, nr, nc in nxt_moves:
            board[nr][nc] = step
            if solve(nr, nc, step + 1):
                return True
            board[nr][nc] = -1
        return False
    if solve(0, 0, 1):
        return board
    return []

