                    q.append((nr, nc))
        return False
    lo, hi = 0, n * n - 1
    ans = hi
    while lo <= hi:
        mid = (lo + hi) // 2
        if can_reach(mid):
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

