def findNumOfValidWords(words, puzzles):
    from collections import Counter
    word_count = Counter()
    for w in words:
        mask = 0
        for ch in w:
            mask |= 1 << (ord(ch) - 97)
        word_count[mask] += 1
    res = []
    for p in puzzles:
        first_bit = 1 << (ord(p[0]) - 97)
        mask = 0
        for ch in p:
            mask |= 1 << (ord(ch) - 97)
        count = 0
        submask = mask
        while submask > 0:
            if submask & first_bit:
                count += word_count[submask]
            submask = (submask - 1) & mask
        res.append(count)
    return res

