def maxScoreWords(words: list[str], letters: list[str], score: list[int]) -> int:
    from collections import Counter
    avail = Counter(letters)
    n = len(words)
    max_val = 0
    for mask in range(1 << n):
        needed = Counter()
        word_score = 0
        for i in range(n):
            if (mask & (1 << i)):
                for ch in words[i]:
