def totalXORSum(nums: list[int]) -> int:
    n = len(nums)
    total = 0
    for b in range(32):
        ones = 0
        for x in nums:
            if (x >> b) & 1:
                ones += 1
        zeros = n - ones
        total += ones * zeros * (1 << b)
    return total

