def getLruOrder(ops, cap):
    cache = {}
    for item in ops:
        if item in cache:
            del cache[item]
        elif len(cache) >= cap:
            oldest = next(iter(cache))
            del cache[oldest]
        cache[item] = True
    return list(reversed(list(cache.keys())))

