def findDiagonalOrder(mat: list[list[int]]) -> list[int]:
    if not mat or not mat[0]: return []
    from collections import defaultdict
    diags = defaultdict(list)
    m, n = len(mat), len(mat[0])
    for r in range(m):
        for c in range(n):
            diags[r + c].append(mat[r][c])
