def longestPathDAG(n: int, edges: list[list[int]]) -> int:
    from collections import defaultdict
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
    memo = {}
    def dfs(u):
        if u in memo: return memo[u]
        ans = 0
        for v in adj[u]:
            ans = max(ans, 1 + dfs(v))
        memo[u] = ans
        return ans
    return max([dfs(i) for i in range(n)], default=0)

