def shortestCycleLength(n: int, edges: list[list[int]]) -> int:
    from collections import defaultdict, deque
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    ans = float('inf')
    for i in range(n):
        dist = {i: 0}
        q = deque([(i, -1)])
        while q:
            u, parent = q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    q.append((v, u))
                elif v != parent:
                    ans = min(ans, dist[u] + dist[v] + 1)
    return ans if ans != float('inf') else -1

