def sequenceReconstruction(nums: list[int], sequences: list[list[int]]) -> bool:
    from collections import defaultdict, deque
    n = len(nums)
    adj = defaultdict(set)
    in_deg = [0] * (n + 1)
    for seq in sequences:
        for i in range(len(seq) - 1):
            u, v = seq[i], seq[i + 1]
            if 1 <= u <= n and 1 <= v <= n:
                if v not in adj[u]:
                    adj[u].add(v)
                    in_deg[v] += 1
    q = deque([i for i in range(1, n + 1) if in_deg[i] == 0])
    res = []
    while q:
        if len(q) > 1: return False
        curr = q.popleft()
        res.append(curr)
        for nxt in adj[curr]:
