def largestIsland(grid: list[list[int]]) -> int:
    n = len(grid)
    island_id = 2
    area = {}
    def dfs(r, c, i_id):
        grid[r][c] = i_id
        size = 1
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == 1:
                size += dfs(nr, nc, i_id)
        return size
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                area[island_id] = dfs(r, c, island_id)
                island_id += 1
    ans = max(area.values(), default=0)
    if ans < n * n: ans = max(ans, 1)
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                seen_islands = set()
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] > 1:
                        seen_islands.add(grid[nr][nc])
                potential = 1 + sum(area[i] for i in seen_islands)
                ans = max(ans, potential)
