                        elif dist[nxt] == dist[w] + 1:
                            parents[nxt].add(w)
    if not found: return []
    res = []
    def backtrack(curr, path):
        if curr == beginWord:
            res.append(path[::-1])
            return
        for p in parents[curr]:
            backtrack(p, path + [p])
    backtrack(endWord, [endWord])
    return sorted(res)

