    n = len(graph)
    parent = list(range(n))
    size = [1] * n
    def find(i):
        if parent[i] == i: return i
        parent[i] = find(parent[i])
        return parent[i]
    for i in range(n):
        for j in range(i + 1, n):
            if graph[i][j] == 1:
                ri, rj = find(i), find(j)
                if ri != rj:
                    parent[ri] = rj
                    size[rj] += size[ri]
    from collections import Counter
    initial.sort()
    infected_count = Counter(find(i) for i in initial)
    best_node = initial[0]
