def crackSafe(n: int, k: int) -> str:
    if n == 1:
        return "".join(str(i) for i in range(k))
    visited = set()
    res = []
    def dfs(node):
        for x in range(k):
            edge = node + str(x)
            if edge not in visited:
                visited.add(edge)
                dfs(edge[1:])
                res.append(str(x))
    start = "0" * (n - 1)
    dfs(start)
    return start + "".join(res[::-1])

